diff --git a/tests/fefo.test.js b/tests/fefo.test.js
new file mode 100644
index 0000000..aa48768
--- /dev/null
+++ b/tests/fefo.test.js
@@ -0,0 +1,33 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { consume } from "../src/domain/batches.js";
+import { app, fresh } from "./helpers.js";
+
+const at = "2026-10-28T10:00:00Z";
+
+test("cooking bechamel takes the milk batch expiring first (HD-1022 before HD-1026)", async () => {
+  const { handle, store } = app();
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 10 } });
+  assert.equal(res.status, 200);
+  const milkUsed = res.body.used.find((u) => u.itemId === 2);
+  assert.deepEqual(milkUsed.batches, [{ batchId: 4, qty: 2 }]);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1022").qty, 0);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1026").qty, 8);
+});
+
+test("consume follows FEFO: earliest expiry, no-expiry last, then receivedOn and id", () => {
+  const store = fresh();
+  store.data.batches = [
+    { id: 10, itemId: 2, lot: "NO-EXP-LATE", qty: 1, receivedOn: "2026-10-20", expires: null, location: "fridge" },
+    { id: 12, itemId: 2, lot: "SAME-EXP-HIGHER-ID", qty: 1, receivedOn: "2026-10-21", expires: "2026-11-05", location: "fridge" },
+    { id: 11, itemId: 2, lot: "SAME-EXP-LOWER-ID", qty: 1, receivedOn: "2026-10-21", expires: "2026-11-05", location: "fridge" },
+    { id: 13, itemId: 2, lot: "SAME-EXP-EARLIER-RECV", qty: 1, receivedOn: "2026-10-19", expires: "2026-11-05", location: "fridge" },
+    { id: 14, itemId: 2, lot: "SOONEST-EXP", qty: 1, receivedOn: "2026-10-27", expires: "2026-10-29", location: "fridge" },
+    { id: 15, itemId: 2, lot: "NO-EXP-EARLY", qty: 1, receivedOn: "2026-10-18", expires: null, location: "fridge" },
+  ];
+  const used = consume(store, 2, 6, { at, ref: "test:fefo" });
+  assert.deepEqual(
+    used.map((u) => u.batchId),
+    [14, 13, 11, 12, 15, 10],
+  );
+});
